  const issueHref = (i) => { const c = i && (i.homeTypes || []).map((t) => C.catalogue(t)).find(Boolean); return `#/library/issues${c ? '/' + encodeURIComponent(c.code) + '/' + encodeURIComponent(i.id) : ''}`; };
