      $$('input[name=wt]', el).forEach((r) => r.onchange = () => { sc.workType = r.value; if (r.value !== 'calibration') sc.probe = null; if (r.value === 'pm' && isNew) sc.anchor = 'last'; if (r.value === 'calibration' && isNew) { sc.every = { n: 1, unit: 'month' }; sc.anchor = 'fixed'; } draw(); });
