    const f = S.sheet.draft; if (!f.forTypes) f.forTypes = []; delete f.forType;
    const USE_LABEL = { pm: 'Maintenance (a scheduled service)', fix: 'Fix (resolves a cause)', round: 'Round (a routine check)', test: 'Manual testing (a sample tested by hand)', calibration: 'Calibration', condition: 'Condition-based job' };
